steps.expression:
// #Previous.Reader is the open response body. Reading it line by line
// keeps memory flat no matter how long the answer turns out to be.
string line;
while ((line = #Previous.Reader.ReadLine()) != null)
{
    if (string.IsNullOrWhiteSpace(line))
        continue;

    // Each line leaves through the boundary event, so the caller sees
    // the answer arriving instead of waiting for all of it.
    Action.BoundaryEvents["Event_Chunk"].Raise(line);
}

// The stream itself is the result; there is nothing left to return.
return null;

